// Keyed lookup: `${stateCode}-${districtNumber}` → RepInfo
export const REPS_BY_KEY: Map<string, RepInfo> = new Map(
  REPS.map((r) => [`${r.stateCode}-${r.districtNumber}`, r])
);

// State-grouped lookup: stateCode → RepInfo[] (sorted by district)
export const REPS_BY_STATE: Map<StateCode, RepInfo[]> = (() => {
  const m = new Map<StateCode, RepInfo[]>();
  for (const r of REPS) {
    const arr = m.get(r.stateCode) ?? [];
    arr.push(r);
    m.set(r.stateCode, arr);
  }
  for (const arr of m.values()) arr.sort((a, b) => a.districtNumber - b.districtNumber);
  return m;
})();

export function repForDistrict(stateCode: StateCode, districtNumber: number | null): RepInfo | null {
  if (districtNumber === null) return null;
  return REPS_BY_KEY.get(`${stateCode}-${districtNumber}`) ?? null;
}
